class Solution {
public:
    int diagonalPrime(std::vector<std::vector<int>>& nums) {
        auto isPrime = [](int x) {
            if (x < 2) return false;
            for (int d = 2; d * d <= x; ++d) {
                if (x % d == 0) return false;
            }
            return true;
        };
        int n = nums.size();
        int max_p = 0;
        for (int i = 0; i < n; ++i) {
            int v1 = nums[i][i];
            int v2 = nums[i][n - 1 - i];
            if (isPrime(v1)) max_p = std::max(max_p, v1);
            if (isPrime(v2)) max_p = std::max(max_p, v2);
        }
        return max_p;
    }
};

class Solution {
    public int diagonalPrime(int[][] nums) {
        int n = nums.length;
        int maxP = 0;
        for (int i = 0; i < n; i++) {
            int v1 = nums[i][i];
            int v2 = nums[i][n - 1 - i];
            if (isPrime(v1)) maxP = Math.max(maxP, v1);
            if (isPrime(v2)) maxP = Math.max(maxP, v2);
        }
        return maxP;
    }
    private boolean isPrime(int x) {
        if (x < 2) return false;
        for (int d = 2; d * d <= x; d++) {
            if (x % d == 0) return false;
        }
        return true;
    }
}

